     const timeout = setTimeout(() => {
       cleanup();
       resolve(data || null);
     }, 100); // 100ms timeout for stdin

     process.stdin.setEncoding("utf8");
     process.stdin.on("data", onData);
     process.stdin.on("end", onEnd);
     process.stdin.on("error", onError);
