1322	async function pullRebaseBeforePush(
1323	  worktreeDir: string,
1324	  branchName: string,
1325	  debug: boolean,
1326	  options?: ShadowOptions,
1327	): Promise<boolean> {
1328	  try {
1329	    // Fetch latest remote state for the shadow branch specifically.
1330	    // Using the worktree dir for fetch ensures we use the branch's tracking config.
1331	    try {
1332	      await runGitAsync(worktreeDir, ["fetch"]);
1333	    } catch {
1334	      if (debug) {
1335	        console.error("[DEBUG] Shadow pull-rebase: fetch failed, skipping pull");
1336	      }
1337	      // Fetch failure is non-fatal — push may still succeed if already up to date
1338	      return true;
1339	    }
1340	
1341	    // AC: @config-shadow ac-3 — resolve the configured remote name from git config
1342	    // instead of hardcoding "origin", so custom shadow.remote setups work correctly
1343	    const projectRoot = path.dirname(worktreeDir);
1344	    let remoteName = "origin";
1345	    try {
1346	      const { stdout } = await runGitAsync(worktreeDir, [
1347	        "config",
1348	        `branch.${branchName}.remote`,
1349	      ]);
1350	      const configured = stdout.trim();
1351	      if (configured) {
1352	        remoteName = configured;
1353	      }
1354	    } catch {
1355	      // Fall back to origin if config lookup fails
1356	    }
1357	
1358	    const remoteHasBranch = await remoteBranchExists(projectRoot, branchName, remoteName);
1359	    if (!remoteHasBranch) {
1360	      if (debug) {
1361	        console.error("[DEBUG] Shadow pull-rebase: no remote branch yet, skipping pull");
1362	      }
1363	      return true;
1364	    }
1365	
1366	    // Check if there are any upstream changes to integrate.
1367	    // If local is already at or ahead of remote, skip the pull.
1368	    try {
1369	      const { stdout } = await runGitAsync(worktreeDir, [
1370	        "rev-list",
1371	        "--count",
1372	        `${branchName}..@{upstream}`,
1373	      ]);
1374	      const behindCount = parseInt(stdout.trim(), 10);
1375	      if (behindCount === 0) {
1376	        if (debug) {
1377	          console.error("[DEBUG] Shadow pull-rebase: already up to date with remote");
1378	        }
1379	        return true;
1380	      }
1381	    } catch {
1382	      // rev-list may fail if upstream isn't set — proceed with pull attempt
1383	    }
1384	
1385	    // Try fast-forward first (cleanest, no rebase needed)
1386	    try {
1387	      await runGitAsync(worktreeDir, ["pull", "--ff-only"]);
1388	      if (debug) {
1389	        console.error("[DEBUG] Shadow pull-rebase: fast-forward succeeded");
1390	      }
1391	      return true;
1392	    } catch {
1393	      // FF failed, need rebase
1394	    }
1395	
1396	    // Fall back to rebase — the kspec merge driver handles YAML conflicts
1397	    try {
1398	      await runGitAsync(worktreeDir, ["pull", "--rebase"]);
1399	      if (debug) {
1400	        console.error("[DEBUG] Shadow pull-rebase: rebase succeeded");
1401	      }
1402	      return true;
1403	    } catch {
1404	      // Rebase failed — abort and report
1405	    }
1406	
1407	    // Abort the failed rebase so local state is clean
1408	    try {
1409	      await runGitAsync(worktreeDir, ["rebase", "--abort"]);
1410	    } catch {
1411	      // May not be in rebase state
1412	    }
1413	
1414	    if (debug) {
1415	      console.error("[DEBUG] Shadow pull-rebase: conflict detected, push skipped");
1416	    }
1417	    return false;
1418	  } catch (err) {
1419	    if (debug) {
1420	      console.error("[DEBUG] Shadow pull-rebase error:", err);
1421	    }
1422	    // Pull failure is non-fatal — still attempt push
