1447	  // AC: @shadow-sync ac-8 - Auto-configure tracking if main has remote but shadow doesn't
1448	  const projectRoot = path.dirname(worktreeDir);
1449	  const trackingResult = await ensureRemoteTracking(worktreeDir, projectRoot, options);
1450	
1451	  // AC: @config-shadow ac-6 — log guidance if named remote doesn't exist
1452	  if (!trackingResult.success && trackingResult.missingRemote) {
1453	    if (debug) {
1454	      console.error(`[DEBUG] Shadow push: ${trackingResult.guidance}`);
1455	    }
1456	    return;
1457	  }
1458	
1459	  // Check if tracking is configured before attempting push
1460	  if (!(await hasRemoteTracking(worktreeDir, options))) {
1461	    if (debug) {
1462	      console.error(
1463	        "[DEBUG] Shadow push: No remote tracking configured, skipping",
1464	      );
1465	    }
1466	    return; // AC: @shadow-sync ac-4 - silently skip if no tracking
1467	  }
1468	
1469	  // AC: @config-shadow ac-11 — pull-rebase before pushing to integrate remote changes
1470	  const branchName = getBranchName(options);
1471	  const pullOk = await pullRebaseBeforePush(worktreeDir, branchName, debug, options);
1472	  if (!pullOk) {
1473	    noteShadowPushFailure(
1474	      worktreeDir,
1475	      "Pull-rebase failed due to conflicts. Run `kspec shadow resolve` to fix.",
